//! Replays reference traces generated by the Python model (`python -m opod.golden`).
//! The firmware core must make the same decisions (mode, faults, pump, polarity) and produce the
//! same TEC current within f32 tolerance, and must produce byte-identical OPL frames.

use opod_core::control::{Inputs, Mode, ZoneController};
use opod_core::protocol::{self, MAX_BODY};
use serde_json::Value;

const CURRENT_TOL_A: f32 = 0.02;

fn load() -> Value {
    serde_json::from_str(include_str!("vectors/golden.json")).expect("golden.json")
}

fn opt(v: &Value) -> Option<f32> {
    v.as_f64().map(|x| x as f32)
}

fn mode(m: Mode) -> u64 {
    m as u64
}

#[test]
fn control_scenarios_match_python_reference() {
    let data = load();
    let scenarios = data["scenarios"].as_array().unwrap();
    assert!(scenarios.len() >= 8);
    for sc in scenarios {
        let name = sc["name"].as_str().unwrap();
        let mut c = ZoneController::new(sc["i_max"].as_f64().unwrap() as f32);
        let mut max_err = 0.0f32;
        for (k, row) in sc["steps"].as_array().unwrap().iter().enumerate() {
            let t = row[0].as_f64().unwrap();
            let dt = row[1].as_f64().unwrap() as f32;
            for ev in row[2].as_array().unwrap() {
                match ev[0].as_str().unwrap() {
                    "set_target" => c.set_target(opt(&ev[1]), t),
                    "heartbeat" => c.heartbeat(t),
                    "clear_faults" => c.clear_faults(),
                    other => panic!("unknown event {other}"),
                }
            }
            let i = &row[3];
            let inp = Inputs {
                t_water: opt(&i[0]),
                t_hot_face: opt(&i[1]),
                flow_lpm: i[2].as_f64().unwrap() as f32,
                leak: i[3].as_u64().unwrap() != 0,
                water_ok: i[4].as_u64().unwrap() != 0,
            };
            let o = c.update(&inp, t, dt);
            let e = &row[4];
            let ctx = format!("{name} step {k} t={t}");
            assert_eq!(o.pump_on, e[1].as_u64().unwrap() != 0, "pump {ctx}");
            assert_eq!(mode(o.mode), e[3].as_u64().unwrap(), "mode {ctx}");
            assert_eq!(o.faults.0 as u64, e[4].as_u64().unwrap(), "faults {ctx}");
            assert_eq!(o.polarity as i64, e[5].as_i64().unwrap(), "polarity {ctx}");
            let err = (o.tec_current - e[0].as_f64().unwrap() as f32).abs();
            max_err = max_err.max(err);
            assert!(err <= CURRENT_TOL_A, "current {ctx}: rust {} python {}", o.tec_current, e[0]);
            assert!((o.fan_duty - e[2].as_f64().unwrap() as f32).abs() <= 0.01, "fan {ctx}");
        }
        eprintln!("{name}: max current deviation {max_err:.5} A");
    }
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

#[test]
fn protocol_frames_are_byte_identical() {
    let data = load();
    for f in data["frames"].as_array().unwrap() {
        let seq = f["seq"].as_u64().unwrap() as u8;
        let typ = f["type"].as_u64().unwrap() as u8;
        let payload = unhex(f["payload"].as_str().unwrap());
        let wire = unhex(f["wire"].as_str().unwrap());
        let mut out = [0u8; protocol::MAX_WIRE];
        let n = protocol::encode(seq, typ, &payload, &mut out).unwrap();
        assert_eq!(&out[..n], &wire[..], "encode type {typ:#x}");
        let mut scratch = [0u8; MAX_BODY];
        let fr = protocol::decode(&wire[..wire.len() - 1], &mut scratch).unwrap();
        assert_eq!((fr.seq, fr.typ, fr.payload), (seq, typ, &payload[..]));
    }
}

#[test]
fn telemetry_pack_matches_python() {
    let data = load();
    let tel = data["frames"].as_array().unwrap().iter().find(|f| f["type"] == 0x80).unwrap();
    let expect = unhex(tel["payload"].as_str().unwrap());
    let side = protocol::SideTelemetry {
        t_water: 2150, t_hot_face: 4010, target: 2100, tec_ma: 3200, flow_mlpm: 480, fan_pct: 55, mode: 1, faults: 0,
    };
    let t = protocol::Telemetry {
        uptime_ms: 123456,
        t_ambient: 2300,
        water_level_pct: 87,
        sides: [side, protocol::SideTelemetry { faults: 0x0011, mode: 2, ..side }],
    };
    let mut out = [0u8; protocol::TELEMETRY_LEN];
    t.pack(&mut out);
    assert_eq!(&out[..], &expect[..]);
}
